1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	import java.util.Map;
15	
16	/**
17	 * Maps Owner & OwnerDto using Mapstruct
18	 */
19	@Mapper(uses = PetMapper.class)
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
23	    @Mapping(target = "initials", expression = "java(initials(owner))")
24	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
25	    @Mapping(target = "membershipTier", expression = "java(membershipTier(owner))")
26	    @Mapping(target = "locality", expression = "java(locality(owner))")
27	    @Mapping(target = "bulkSignupWarning", expression = "java(bulkSignupWarning(owner))")
28	    OwnerDto toOwnerDto(Owner owner);
29	
30	    Owner toOwner(OwnerDto ownerDto);
31	
32	    /**
33	     * Formats an owner's stored names as {@code 'LastName, FirstName'}.
34	     */
35	    default String displayName(Owner owner) {
36	        if (owner == null) {
37	            return null;
38	        }
39	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
40	        String firstName = owner.getFirstName() == null ? "" : owner.getFirstName();
41	        return lastName + ", " + firstName;
42	    }
43	
44	    /**
45	     * Returns the upper-cased first letters of firstName and lastName,
46	     * dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
47	     */
48	    default String initials(Owner owner) {
49	        if (owner == null) {
50	            return null;
51	        }
52	        StringBuilder sb = new StringBuilder();
53	        String firstName = owner.getFirstName();
54	        String lastName = owner.getLastName();
55	        if (firstName != null && !firstName.isEmpty()) {
56	            sb.append(Character.toUpperCase(firstName.charAt(0))).append('.');
57	        }
58	        if (lastName != null && !lastName.isEmpty()) {
59	            sb.append(Character.toUpperCase(lastName.charAt(0))).append('.');
60	        }
61	        return sb.toString();
62	    }
63	
64	    /**
65	     * Formats the owner's membership number as {@code '<customerCode>-M<YY>'}: the customer
66	     * code, the literal {@code '-M'}, and the last two digits of the registrationDate year.
67	     * Returns {@code null} unless both the customer code and registration date are present.
68	     */
69	    default String membershipNumber(Owner owner) {
70	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
71	            return null;
72	        }
73	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
74	        return owner.getCustomerCode() + "-M" + yy;
75	    }
76	
77	    /**
78	     * Returns the owner's membership tier: {@code 'SILVER'} when the owner has no
79	     * namesakes (namesakeCount is 0) and an email address is present; otherwise
80	     * {@code 'BRONZE'}.
81	     */
82	    default String membershipTier(Owner owner) {
83	        if (owner == null) {
84	            return null;
85	        }
86	        Integer namesakeCount = owner.getNamesakeCount();
87	        String email = owner.getEmail();
88	        boolean noNamesakes = namesakeCount != null && namesakeCount == 0;
89	        boolean hasEmail = email != null && !email.isEmpty();
90	        return (noNamesakes && hasEmail) ? "SILVER" : "BRONZE";
91	    }
92	
93	    /** Fixed city-to-region table used to derive an owner's locality. */
94	    Map<String, String> CITY_REGION = Map.of(
95	        "Sydney", "NSW",
96	        "Melbourne", "VIC",
97	        "Brisbane", "QLD");
98	
99	    /**
100	     * Derives the owner's locality (region) from the city using the fixed city-to-region
101	     * table ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}).
102	     * Returns {@code "UNKNOWN"} when the city is {@code null} or not in the table.
103	     */
104	    default String locality(Owner owner) {
105	        if (owner == null) {
106	            return null;
107	        }
108	        String city = owner.getCity();
109	        return city == null ? "UNKNOWN" : CITY_REGION.getOrDefault(city, "UNKNOWN");
110	    }
111	
112	    /**
113	     * Whether the owner carries the bulk-signup warning (more than 80 owners already created
114	     * on its registration day at creation time). A {@code null} stored value is treated as
115	     * {@code false}, so the field is always present in the response.
116	     */
117	    default Boolean bulkSignupWarning(Owner owner) {
118	        if (owner == null) {
119	            return null;
120	        }
121	        return Boolean.TRUE.equals(owner.getBulkSignupWarning());
122	    }
123	
124	    @Mapping(target = "id", ignore = true)
125	    @Mapping(target = "pets", ignore = true)
126	    Owner toOwner(OwnerFieldsDto ownerDto);
127	
128	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
129	
130	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
131	
132	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
133	        OwnerPageDto ownerPageDto = new OwnerPageDto();
134	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
135	        ownerPageDto.setPage(ownerPage.getNumber());
136	        ownerPageDto.setSize(ownerPage.getSize());
137	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
138	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
139	        return ownerPageDto;
140	    }
141	}
