98	
99	    /**
100	     * Derives the owner's locality (region) from the city using the fixed city-to-region
101	     * table ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}).
102	     * Returns {@code "UNKNOWN"} when the city is {@code null} or not in the table.
103	     */
104	    default String locality(Owner owner) {
105	        if (owner == null) {
106	            return null;
107	        }
108	        String city = owner.getCity();
109	        return city == null ? "UNKNOWN" : CITY_REGION.getOrDefault(city, "UNKNOWN");
110	    }
111	
112	    /**
113	     * Whether the owner carries the bulk-signup warning (more than 80 owners already created
114	     * on its registration day at creation time). A {@code null} stored value is treated as
115	     * {@code false}, so the field is always present in the response.
116	     */
117	    default Boolean bulkSignupWarning(Owner owner) {
118	        if (owner == null) {
119	            return null;
120	        }
121	        return Boolean.TRUE.equals(owner.getBulkSignupWarning());
122	    }
123	
124	    @Mapping(target = "id", ignore = true)
125	    @Mapping(target = "pets", ignore = true)
126	    Owner toOwner(OwnerFieldsDto ownerDto);
127	
