221	    @Override
222	    @Transactional
223	    public void savePet(Pet pet) throws DataAccessException {
224	        pet.setType(findPetTypeById(pet.getType().getId()));
225	        petRepository.save(pet);
226	    }
227	
228	    @Override
229	    @Transactional
230	    public void saveVisit(Visit visit) throws DataAccessException {
231	        visitRepository.save(visit);
232	
233	    }
234	
235	    @Override
236	    @Transactional(readOnly = true)
237	    public Collection<Vet> findVets() throws DataAccessException {
238	        return vetRepository.findAll();
239	    }
240	
241	    @Override
242	    @Transactional
243	    public void saveOwner(Owner owner) throws DataAccessException {
244	        ownerRepository.save(owner);
245	
246	    }
247	
248	    @Override
249	    @Transactional
250	    public void createOwner(Owner owner) throws DataAccessException {
251	        createOwner(owner, false);
252	    }
253	
254	    @Override
255	    @Transactional
256	    public void createOwner(Owner owner, boolean sharesHousehold) throws DataAccessException {
257	        rejectWhenDailyLimitReached(owner);
258	        rejectWhenCityAtCapacity(owner);
259	        assignHousehold(owner, sharesHousehold);
260	        if (owner.getCustomerCode() == null) {
261	            owner.setCustomerCode(nextCustomerCode(owner));
262	        }
263	        if (owner.getNamesakeCount() == null) {
264	            owner.setNamesakeCount(countNamesakes(owner));
265	        }
266	        owner.setBulkSignupWarning(exceedsBulkSignupThreshold(owner));
267	        ownerRepository.save(owner);
268	    }
269	
270	    /** Number of owners created on a single day beyond which the bulk-signup warning is raised. */
271	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
272	
273	    /**
274	     * Whether more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created
275	     * today (compared by {@code registrationDate}), evaluated before this owner is persisted so it
276	     * reflects the owners present at creation time. The new owner's registration date, defaulted to
277	     * today by the controller, determines which day is counted — the same accumulation path as the
278	     * daily-limit rule.
279	     */
280	    private boolean exceedsBulkSignupThreshold(Owner owner) {
281	        LocalDate day = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
282	        return countOwnersRegisteredOn(day) > BULK_SIGNUP_WARNING_THRESHOLD;
283	    }
284	
285	    /**
286	     * Count the existing owners that already share this owner's first name and last name,
287	     * compared case-insensitively (with surrounding/collapsed whitespace ignored). Evaluated
288	     * before the owner is persisted, so it reflects the owners present at creation time.
289	     */
290	    private int countNamesakes(Owner owner) {
291	        String firstName = IdentityNormalizer.normalize(owner.getFirstName());
292	        String lastName = IdentityNormalizer.normalize(owner.getLastName());
293	        return (int) ownerRepository.findAll().stream()
294	            .filter(existing -> firstName.equals(IdentityNormalizer.normalize(existing.getFirstName()))
295	                && lastName.equals(IdentityNormalizer.normalize(existing.getLastName())))
296	            .count();
297	    }
298	
299	    /**
300	     * Reconcile the owner's household. Owners are in the same household when their last name and
301	     * address match (compared case-insensitively with collapsed whitespace). When another owner
302	     * already lives there, the create is rejected with {@link DuplicateHouseholdException} unless
303	     * {@code sharesHousehold} is set, in which case the new owner and every existing member are
304	     * given the same stable shared {@code householdId}.
305	     */
306	    private void assignHousehold(Owner owner, boolean sharesHousehold) {
307	        String lastName = IdentityNormalizer.normalize(owner.getLastName());
308	        String address = AddressNormalizer.canonical(owner.getAddress());
309	        List<Owner> householdMembers = ownerRepository.findAll().stream()
310	            .filter(existing -> lastName.equals(IdentityNormalizer.normalize(existing.getLastName()))
311	                && address.equals(AddressNormalizer.canonical(existing.getAddress())))
312	            .toList();
313	        if (householdMembers.isEmpty()) {
314	            return;
315	        }
316	        if (!sharesHousehold) {
317	            throw new DuplicateHouseholdException(
318	                "an owner with last name " + owner.getLastName() + " already lives at " + owner.getAddress());
319	        }
320	        String householdId = householdMembers.stream()
321	            .map(Owner::getHouseholdId)
322	            .filter(Objects::nonNull)
323	            .findFirst()
324	            .orElseGet(() -> deriveHouseholdId(lastName, address));
325	        owner.setHouseholdId(householdId);
326	        for (Owner member : householdMembers) {
327	            if (!householdId.equals(member.getHouseholdId())) {
328	                member.setHouseholdId(householdId);
329	                ownerRepository.save(member);
330	            }
331	        }
332	    }
333	
334	    /**
335	     * Derive a stable, shared household identifier from the normalized last name and address, so
336	     * every owner in the same household deterministically maps to the same value.
337	     */
338	    private static String deriveHouseholdId(String normalizedLastName, String normalizedAddress) {
339	        String key = normalizedLastName + "\n" + normalizedAddress;
340	        return UUID.nameUUIDFromBytes(key.getBytes(StandardCharsets.UTF_8)).toString();
341	    }
342	
343	    /** Maximum number of owners that may be created on any single day (by registration date). */
344	    private static final long DAILY_OWNER_LIMIT = 100L;
345	
346	    /**
347	     * Reject the create when {@value #DAILY_OWNER_LIMIT} or more owners have already been created
348	     * today (compared by {@code registrationDate}). Evaluated before the owner is persisted, so it
349	     * reflects the owners present at creation time. The new owner's own registration date, defaulted
350	     * to today by the controller, determines which day the limit is checked against.
351	     */
352	    private void rejectWhenDailyLimitReached(Owner owner) {
353	        LocalDate day = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
354	        if (countOwnersRegisteredOn(day) >= DAILY_OWNER_LIMIT) {
355	            throw new DailyOwnerLimitExceededException(
356	                DAILY_OWNER_LIMIT + " or more owners have already been created on " + day);
357	        }
358	    }
359	
360	    /**
361	     * Count the existing owners whose {@code registrationDate} equals the given day. Evaluated
362	     * before the owner is persisted, so it reflects the owners present at creation time.
363	     */
364	    private long countOwnersRegisteredOn(LocalDate day) {
365	        return ownerRepository.findAll().stream()
366	            .filter(existing -> day.equals(existing.getRegistrationDate()))
367	            .count();
368	    }
369	
370	    /** Maximum number of owners allowed to live in any single city. */
371	    private static final long CITY_CAPACITY = 50L;
372	
373	    /**
374	     * Reject the create when the owner's city already contains {@value #CITY_CAPACITY} or more
375	     * owners (compared case-insensitively with collapsed whitespace). Evaluated before the owner
376	     * is persisted, so it reflects the owners present at creation time.
377	     */
378	    private void rejectWhenCityAtCapacity(Owner owner) {
379	        if (countOwnersInCity(owner) >= CITY_CAPACITY) {
380	            throw new CityCapacityExceededException(
381	                "city " + owner.getCity() + " already contains " + CITY_CAPACITY + " or more owners");
382	        }
383	    }
384	
385	    /**
386	     * Count the existing owners that already live in this owner's city, compared
387	     * case-insensitively (with surrounding/collapsed whitespace ignored). Evaluated before the
388	     * owner is persisted, so it reflects the owners present at creation time.
389	     */
390	    private long countOwnersInCity(Owner owner) {
391	        String city = IdentityNormalizer.normalize(owner.getCity());
392	        return ownerRepository.findAll().stream()
393	            .filter(existing -> city.equals(IdentityNormalizer.normalize(existing.getCity())))
394	            .count();
395	    }
396	
397	    /**
398	     * Builds the customer code {@code '<CITY3>-<LAST3>-<NNNN>'}: the upper-cased first
399	     * three letters of the owner's {@code city}, a hyphen, the upper-cased first three
400	     * letters of {@code lastName}, a hyphen, and a 4-digit zero-padded per-city sequence
401	     * equal to one more than the number of owners already in that city (compared
402	     * case-insensitively with collapsed whitespace).
403	     */
404	    private String nextCustomerCode(Owner owner) {
405	        String city3 = prefix3(owner.getCity());
406	        String last3 = prefix3(owner.getLastName());
407	        long sequence = countOwnersInCity(owner) + 1L;
408	        return String.format("%s-%s-%04d", city3, last3, sequence);
409	    }
410	
411	    /**
412	     * Returns the upper-cased first three letters of {@code value}, or fewer when the value
413	     * is shorter; a {@code null} value yields an empty string.
414	     */
415	    private static String prefix3(String value) {
416	        String name = value == null ? "" : value;
417	        return name.substring(0, Math.min(3, name.length())).toUpperCase();
418	    }
419	
420	    @Override
421	    @Transactional(readOnly = true)
422	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
423	        return ownerRepository.findByLastName(lastName);
424	    }
425	
426	    @Override
427	    @Transactional(readOnly = true)
428	    public Collection<Visit> findVisitsByPetId(int petId) {
429	        return visitRepository.findByPetId(petId);
430	    }
431	
432	    @Override
433	    @Transactional(readOnly = true)
434	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
435	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
436	    }
437	
438	    private <T> T findEntityById(Supplier<T> supplier) {
439	        try {
440	            return supplier.get();
441	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
442	            // Just ignore not found exceptions for Jdbc/Jpa realization
443	            return null;
444	        }
445	    }
446	
447	}
